// Interface contract
interface Resizable {
    void resizeWidth(int width);
    void resizeHeight(int height);
}

// Class implementing interface
class Rectangle implements Resizable {
    private int width;
    private int height;

    public Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }

    public int getArea() {
        return width * height;
    }

    public int getPerimeter() {
        return 2 * (width + height);
    }

    // Implementing interface methods (MUST BE PUBLIC!)
    @Override
    public void resizeWidth(int width) {
        this.width = width;
        System.out.println("Width resized to: " + width);
    }

    @Override
    public void resizeHeight(int height) {
        this.height = height;
        System.out.println("Height resized to: " + height);
    }

    public void display() {
        System.out.println("Dimensions: " + width + "x" + height + " | Area: " + getArea() + " | Perimeter: " + getPerimeter());
    }
}

public class ResizableDemo {
    public static void main(String[] args) {
        Rectangle rect = new Rectangle(10, 20);
        System.out.println("Original Rectangle:");
        rect.display();

        System.out.println("\nResizing Rectangle...");
        rect.resizeWidth(15);
        rect.resizeHeight(25);

        System.out.println("\nAfter Resizing:");
        rect.display();
    }
}

