import java.util.Scanner;

// 1. Custom Checked Exception
class DivisionByZeroException extends Exception {
    public DivisionByZeroException(String message) {
        super(message);
    }
}

public class CustomExceptionDemo {
    // 2. Method throwing custom exception using 'throws'
    static double divide(int numerator, int denominator) throws DivisionByZeroException {
        if (denominator == 0) {
            // 3. Explicitly trigger exception using 'throw'
            throw new DivisionByZeroException("Denominator cannot be zero! Division undefined.");
        }
        return (double) numerator / denominator;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter numerator: ");
        int num = sc.nextInt();
        System.out.print("Enter denominator: ");
        int den = sc.nextInt();

        // 4. Guarded block using try-catch-finally
        try {
            double result = divide(num, den);
            System.out.println("Result: " + num + " / " + den + " = " + result);
        } catch (DivisionByZeroException e) {
            System.err.println("Caught Custom Exception: " + e.getMessage());
        } finally {
            // 5. Finally block ALWAYS executes
            System.out.println("Finally block: Resources cleaned up successfully.");
            sc.close();
        }
    }
}

