import java.util.ArrayList;

public class WrapperDemo {
    public static void main(String[] args) {
        // 1. Autoboxing: primitive int to Integer object
        int primitiveVal = 42;
        Integer boxedVal = primitiveVal; // Autoboxing: Integer.valueOf(42)
        System.out.println("Boxed Integer Object: " + boxedVal);

        // 2. Unboxing: Integer object back to primitive int
        int unboxedVal = boxedVal; // Unboxing: boxedVal.intValue()
        System.out.println("Unboxed Primitive int: " + unboxedVal);

        // 3. Autoboxing with Collections (ArrayList only takes Objects!)
        ArrayList<Integer> list = new ArrayList<>();
        list.add(10); // Autoboxing int 10 to Integer
        list.add(20);
        list.add(30);

        // Unboxing during arithmetic
        int sum = 0;
        for (Integer num : list) {
            sum += num; // num is unboxed automatically to int
        }
        System.out.println("Sum of list elements: " + sum);

        // 4. Useful Wrapper Utility Methods
        String strNumber = "500";
        int parsed = Integer.parseInt(strNumber);
        System.out.println("Parsed from string: " + (parsed + 50)); // 550
        System.out.println("42 in Binary: " + Integer.toBinaryString(42));
    }
}

